#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>

int main(int argc, char *argv[]) {
    if (argc < 2) {
        puts("NO_INPUT");
        return 0;
    }
    char *endptr = NULL;
    errno = 0;
    long n = strtol(argv[1], &endptr, 10);
    // Bad input if no digits were found or extra characters remain
    if (endptr == argv[1] || *endptr != '\0') {
        puts("BAD_INPUT");
        return 0;
    }
    // Out of allowed range (the original program limits to 1,000,000)
    if (n > 1000000L) {
        puts("OUT_OF_RANGE");
        return 0;
    }
    // Compute sum of proper divisors of n (positive divisors less than n)
    long sum = 0;
    if (n > 1) {
        for (long i = 1; i * i <= n; ++i) {
            if (n % i == 0) {
                long j = n / i;
                if (i != n) sum += i;          // i is a proper divisor
                if (j != i && j != n) sum += j; // counterpart divisor, avoid double count and n itself
            }
        }
    }
    if (sum < n) {
        printf("n=%ld sum=%ld deficient\n", n, sum);
    } else if (sum == n) {
        printf("n=%ld sum=%ld perfect\n", n, sum);
    } else {
        printf("n=%ld sum=%ld abundant\n", n, sum);
    }
    return 0;
}
